sksl:
uniform shader image;
uniform float2 size;
uniform float4 screen;
uniform float time;
uniform float scale;
uniform float angle;
uniform float mirror;
uniform float fit;
uniform float crop;
uniform float2 stretch;
uniform float2 offset;
uniform float screenSpace;
uniform float mask;
uniform float lineWidth;
uniform float feather;
uniform float edgeStyle;
half4 main(float2 coord) {
    bool onScreen = screenSpace > 0.5;
    float2 c = size * 0.5;
    float2 o = onScreen ? screen.xy + screen.zw * 0.5 : c;
    float unit = 0.5 * (onScreen ? screen.w : min(size.x, size.y)) * max(scale, 0.05);
    float2 st = max(abs(stretch), float2(0.01));
    float a = radians(angle);
    float cs = cos(a);
    float sn = sin(a);
    float2 p = coord - o;
    p = float2(cs * p.x + sn * p.y, -sn * p.x + cs * p.y) / (unit * st);
    float2 r = float2(1.0, 1.7320508);
    float2 h = r * 0.5;
    float2 ga = mod(p, r) - h;
    float2 gb = mod(p - h, r) - h;
    float2 g = dot(ga, ga) < dot(gb, gb) ? ga : gb;
    if (mirror > 0.5) {
        float2 id = p - g;
        float k = mod(floor(id.x + 0.5) + floor(id.y / 1.7320508 * 2.0 + 0.5), 2.0);
        g.x = mix(g.x, -g.x, k);
    }
    float2 aq = abs(g);
    float line = 1.0 - smoothstep(max(lineWidth - feather, 0.0), lineWidth, 1.0 - 2.0 * max(aq.x, dot(aq, float2(0.5, 0.8660254))));
    bool cell = fit > 0.5;
    g *= cell ? float2(min(size.x, size.y) * max(crop, 0.05)) : unit * st;
    g = float2(cs * g.x - sn * g.y, sn * g.x + cs * g.y);
    float2 q = c + g - offset;
    bool outside = coord.x < 0.0 || coord.y < 0.0 || coord.x > size.x || coord.y > size.y;
    if (edgeStyle > 0.5) q = size - abs(mod(q, 2.0 * size) - size);
    if ((cell && (q.x < 0.0 || q.y < 0.0 || q.x > size.x || q.y > size.y)) || (mask > 0.5 && outside)) return half4(0.0);
    half4 color = image.eval(clamp(q, float2(0.5), size - 0.5));
    if (lineWidth > 0.0) color = color * half(1.0 - line) + half4(0.0, 0.0, 0.0, line);
    return mask > 0.5 ? color * image.eval(coord).a : color;
}
